import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const API = 'http://localhost:8080';

function base64urlToBuffer(value) {
  const base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64.padEnd(
    Math.ceil(base64.length / 4) * 4,
    '='
  );

  const binary = atob(padded);

  return Uint8Array.from(binary, char => char.charCodeAt(0));
}

function Register() {
  const [label, setLabel] = useState('');
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);

  const handleRegister = async (event) => {
    event.preventDefault();

    try {
      setLoading(true);
      setMessage('Preparing passkey registration...');

      if (!window.PublicKeyCredential) {
        throw new Error('Your browser does not support WebAuthn.');
      }

      // Step 1: Get CSRF token
      const csrfResponse = await fetch(`${API}/api/csrf`, {
        credentials: 'include'
      });

      if (!csrfResponse.ok) {
        throw new Error('Unable to obtain CSRF token.');
      }

      const csrf = await csrfResponse.json();

      // Step 2: Get registration options
      const optionsResponse = await fetch(
        `${API}/webauthn/register/options`,
        {
          method: 'POST',
          credentials: 'include',
          headers: {
            'X-CSRF-TOKEN': csrf.token
          }
        }
      );

      if (!optionsResponse.ok) {
        throw new Error(
          'Unable to get registration options. Please sign in first.'
        );
      }

      const options = await optionsResponse.json();

      // Decode binary values
      options.challenge = base64urlToBuffer(options.challenge);
      options.user.id = base64urlToBuffer(options.user.id);

      if (options.excludeCredentials) {
        options.excludeCredentials = options.excludeCredentials.map(item => ({
          ...item,
          id: base64urlToBuffer(item.id)
        }));
      }

      setMessage('Please complete passkey verification...');

      // Step 3: Create passkey
      const credential = await navigator.credentials.create({
        publicKey: options
      });

      if (!credential) {
        throw new Error('Passkey registration was cancelled.');
      }

      // Step 4: Send credential to Spring Boot
      const registrationResponse = await fetch(
        `${API}/webauthn/register`,
        {
          method: 'POST',
          credentials: 'include',
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-TOKEN': csrf.token
          },
          body: JSON.stringify({
            publicKey: {
              credential: credential.toJSON(),
              label: label.trim()
            }
          })
        }
      );

      if (!registrationResponse.ok) {
        throw new Error('Passkey registration failed.');
      }

      const result = await registrationResponse.json();

      if (result.success) {
        setMessage('Passkey registered successfully!');
        setLabel('');
      } else {
        throw new Error('Registration was not confirmed.');
      }

    } catch (error) {
      console.error(error);
      setMessage(error.message || 'Registration failed.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container mt-5">
      <div className="row justify-content-center">
        <div className="col-md-5">
          <div className="card shadow p-4">
            <h2 className="text-center mb-4">Register Passkey</h2>

            <form onSubmit={handleRegister}>
              <div className="mb-3">
                <label className="form-label">
                  Passkey Device Name
                </label>

                <input
                  type="text"
                  className="form-control"
                  placeholder="Example: MacBook Passkey"
                  value={label}
                  onChange={(e) => setLabel(e.target.value)}
                  required
                />
              </div>

              <button
                type="submit"
                className="btn btn-success w-100"
                disabled={loading}
              >
                {loading ? 'Registering...' : 'Register Passkey'}
              </button>
            </form>

            {message && (
              <div className="alert alert-info mt-3">
                {message}
              </div>
            )}

            <p className="text-center mt-3">
              <Link to="/">Back to Home</Link>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Register;
